// `createDoubled` is what `const doubled = createMemo(() => count() * 2)` returns
// from a helper: a memo's accessor, typed `() => number` by `solid-js`.
// `createDoubledOpen` is its control, with `returns` left open in the contract.
//
// The signatures are `tsc`-clean for every call `App.tsx` makes, so nothing
// here duplicates a type diagnostic.
export declare function createDoubled(count: () => number): () => number;
export declare function createDoubledOpen(count: () => number): () => number;
